from pathlib import Path
import re
p=Path('src/void-apex-answer-combat-v1.js')
s=p.read_text()

def sub(pattern,repl,label):
    global s
    s2,n=re.subn(pattern,repl,s,count=1,flags=re.S)
    if n!=1: raise SystemExit(f'{label}: expected 1 replacement, got {n}')
    s=s2

sub(r"function drawSplit\(m\)\{.*?\n  function drawBeam\(m\)\{", '''function drawSplit(m){const line=m.line,ux=Math.cos(line.a),uy=Math.sin(line.a),x1=line.cx-ux*line.span,y1=line.cy-uy*line.span,x2=line.cx+ux*line.span,y2=line.cy+uy*line.span,nx=-uy,ny=ux,band=SPLIT_BAND_HALF;if(m.age<m.warn){const p=clamp01(m.age/m.warn);ctx.save();ctx.strokeStyle=`rgba(0,0,0,${.045+p*.075})`;ctx.lineWidth=band*2;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.strokeStyle=`rgba(232,236,246,${.18+p*.58})`;ctx.lineWidth=1.2+p*1.45;ctx.setLineDash([9,11]);ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=`rgba(177,184,203,${.10+p*.22})`;ctx.lineWidth=1;for(const side of[-1,1]){ctx.beginPath();ctx.moveTo(x1+nx*band*side,y1+ny*band*side);ctx.lineTo(x2+nx*band*side,y2+ny*band*side);ctx.stroke();}ctx.restore();return;}const elapsed=m.age-m.warn,alpha=elapsed<=m.active?1:1-clamp01((elapsed-m.active)/m.fade);ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle='rgba(0,0,0,.52)';ctx.lineWidth=(band+4)*2;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.strokeStyle='#000000';ctx.lineWidth=band*2;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.strokeStyle='rgba(190,197,216,.26)';ctx.lineWidth=1.1;for(const side of[-1,1]){ctx.beginPath();ctx.moveTo(x1+nx*band*side,y1+ny*band*side);ctx.lineTo(x2+nx*band*side,y2+ny*band*side);ctx.stroke();}const flowT=performance.now()*.00020;ctx.lineCap='round';for(let i=0;i<14;i++){const speed=.52+(i%4)*.08,q=(i/14+flowT*speed)%1,px=x1+(x2-x1)*q,py=y1+(y2-y1)*q,off=Math.sin(i*2.37+flowT*18)*band*.42,len=5+(i%5)*2.4,bend=Math.cos(i*1.71+flowT*13)*3.5;ctx.strokeStyle=`rgba(${68+(i%3)*9},${50+(i%2)*8},${88+(i%4)*8},${.16+(i%3)*.045})`;ctx.lineWidth=1+(i%3)*.35;ctx.beginPath();ctx.moveTo(px-ux*len+nx*off,py-uy*len+ny*off);ctx.quadraticCurveTo(px+nx*(off+bend),py+ny*(off+bend),px+ux*len+nx*off,py+uy*len+ny*off);ctx.stroke();}ctx.restore();}
  function drawBeam(m){''','draw split')

sub(r"function drawRow\(m\)\{.*?\n  function drawClone\(c\)\{", '''function drawRow(m){for(let i=0;i<m.count;i++){const fake=m.fake.has(i),crumbled=m.crumble.has(i);if(crumbled)continue;if(m.age<m.warn){const p=clamp01(m.age/m.warn),g=rowLaneGeometry(m,i,1),originX=g.dir>0?g.left+12:g.right-12;ctx.save();ctx.fillStyle=fake?`rgba(255,255,255,${.004+p*.010})`:`rgba(0,0,0,${.025+p*.055})`;ctx.strokeStyle=fake?`rgba(255,255,255,${.46+p*.43})`:`rgba(139,111,170,${.34+p*.44})`;ctx.shadowColor=fake?'rgba(255,255,255,.24)':'rgba(72,51,92,.30)';ctx.shadowBlur=fake?5:4;ctx.lineWidth=fake?1.65:1.35;ctx.setLineDash(fake?[10,8]:[5,11]);ctx.beginPath();ctx.moveTo(g.poly[0].x,g.poly[0].y);for(let j=1;j<g.poly.length;j++)ctx.lineTo(g.poly[j].x,g.poly[j].y);ctx.closePath();ctx.fill();ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=fake?`rgba(255,255,255,${.22+p*.36})`:`rgba(104,78,132,${.22+p*.30})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(g.dir>0?g.left:g.right,g.mid);ctx.lineTo(g.dir>0?g.right:g.left,g.mid);ctx.stroke();ctx.fillStyle=fake?'rgba(255,255,255,.74)':'rgba(4,3,7,.94)';ctx.strokeStyle=fake?'rgba(255,255,255,.92)':'rgba(148,115,177,.72)';ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(originX,g.mid,4.2+p*1.8,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();continue;}const elapsed=m.age-m.warn,reach=elapsed<m.active?clamp01(elapsed/.18):1,alpha=elapsed<=m.active?1:1-clamp01((elapsed-m.active)/m.fade),g=rowLaneGeometry(m,i,reach);ctx.save();ctx.globalAlpha=alpha;ctx.shadowColor=fake?'rgba(245,249,255,.36)':'rgba(0,0,0,.95)';ctx.shadowBlur=fake?7:9;ctx.fillStyle=fake?'rgba(235,242,252,.34)':'#000000';ctx.strokeStyle=fake?'rgba(255,255,255,.94)':'rgba(148,112,179,.74)';ctx.lineWidth=fake?1.8:1.55;ctx.beginPath();ctx.moveTo(g.poly[0].x,g.poly[0].y);for(let j=1;j<g.poly.length;j++)ctx.lineTo(g.poly[j].x,g.poly[j].y);ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;if(fake){ctx.strokeStyle='rgba(255,255,255,.56)';ctx.lineWidth=1.1;ctx.setLineDash([13,15]);for(const off of[-.13,.13]){ctx.beginPath();ctx.moveTo(g.dir>0?g.left:g.right,g.mid+(g.y1-g.y0)*off);ctx.lineTo(g.dir>0?g.right:g.left,g.mid+(g.y1-g.y0)*off*.45);ctx.stroke();}ctx.setLineDash([]);}else{ctx.strokeStyle='rgba(76,50,98,.78)';ctx.lineWidth=2.1;for(const off of[-.18,0,.17]){ctx.beginPath();ctx.moveTo(g.dir>0?g.left-14:g.right+14,g.mid+(g.y1-g.y0)*off);ctx.lineTo(g.dir>0?g.poly[6].x-28:g.poly[6].x+28,g.mid+(g.y1-g.y0)*off*.55);ctx.stroke();}}ctx.restore();}}
  function drawClone(c){''','draw row')

old="if(family==='bolt'||family==='heavy'){ctx.translate(p.x,p.y);ctx.rotate(Math.atan2(c.vy,c.vx));ctx.beginPath();ctx.moveTo(c.r*1.8,0);ctx.lineTo(-c.r,-c.r*.72);ctx.lineTo(-c.r*.5,0);ctx.lineTo(-c.r,c.r*.72);ctx.closePath();ctx.fill();ctx.stroke();}"
new="if(family==='bolt'||family==='heavy'){const scale=family==='heavy'?1.18:1.45;ctx.translate(p.x,p.y);ctx.rotate(Math.atan2(c.vy,c.vx));ctx.shadowColor='rgba(225,229,238,.42)';ctx.shadowBlur=5;ctx.strokeStyle='rgba(225,229,238,.78)';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(-c.r*scale*1.4,0);ctx.lineTo(-c.r*scale*4.2,0);ctx.stroke();ctx.fillStyle='#000000';ctx.beginPath();ctx.moveTo(c.r*1.9*scale,0);ctx.lineTo(-c.r*scale,-c.r*.74*scale);ctx.lineTo(-c.r*.45*scale,0);ctx.lineTo(-c.r*scale,c.r*.74*scale);ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(225,229,238,.86)';ctx.lineWidth=1.25;ctx.stroke();}"
if old not in s: raise SystemExit('clone bolt anchor missing')
s=s.replace(old,new,1)
p.write_text(s)
print('patched second-pass Answer presentation')
